<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { api, json } from '../api/client';
import type { Precision, ReleaseTime, ReviewOut, SourceEvent } from '../api/contracts';
import { eventLabel, report, success, timestampLabel } from '../composables/ui';
import PageHeading from '../components/PageHeading.vue';
const proposals = ref<ReviewOut[]>([]), loading = ref(true), status = ref('pending'), selected = ref<ReviewOut | null>(null), saving = ref(false);
const edited = ref<SourceEvent | null>(null), precision = ref<Precision>('unknown'), dateValue = ref(''), endValue = ref(''), dateLabel = ref('');
const pending = computed(() => proposals.value.filter(item => item.status === 'pending').length);
const kinds = ['announcement', 'release', 'episode_release', 'chapter_release', 'volume_release', 'availability', 'pv', 'rumour', 'sequel', 'adaptation', 'delay', 'cancellation'];
async function load() { loading.value = true; try { proposals.value = await api<ReviewOut[]>(`/review?status=${status.value}`); } catch (err) { report(err); } finally { loading.value = false; } }
function inspect(item: ReviewOut) { selected.value = item; edited.value = structuredClone(item.payload); const release = item.payload.release; precision.value = release?.precision || 'unknown'; dateValue.value = release?.timestamp || (precision.value === 'year' ? release?.start?.slice(0, 4) : precision.value === 'month' ? release?.start?.slice(0, 7) : release?.start) || ''; endValue.value = release?.end || ''; dateLabel.value = release?.label || ''; }
function releaseTime(): ReleaseTime {
  const label = dateLabel.value.trim();
  if (precision.value === 'unknown') return { precision: 'unknown', label: label || 'TBA', start: null, end: null, timestamp: null };
  if (!dateValue.value) throw new Error('Enter a date or choose “unknown”.');
  if (precision.value === 'instant') { if (!/(Z|[+-]\d{2}:\d{2})$/.test(dateValue.value)) throw new Error('Use an ISO timestamp with a timezone, for example 2027-04-02T21:00:00+09:00.'); return { precision: 'instant', timestamp: dateValue.value, timezone: edited.value?.release?.timezone || 'UTC', label }; }
  if (precision.value === 'year') { if (!/^\d{4}$/.test(dateValue.value) || Number(dateValue.value) < 1) throw new Error('Enter a four-digit year.'); return { precision: 'year', start: `${dateValue.value}-01-01`, end: `${dateValue.value}-12-31`, label: label || dateValue.value }; }
  if (precision.value === 'month') { if (!/^\d{4}-\d{2}$/.test(dateValue.value)) throw new Error('Enter a month in YYYY-MM format.'); const [year, month] = dateValue.value.split('-').map(Number); const lastDay = new Date(Date.UTC(year!, month!, 0)).getUTCDate(); return { precision: 'month', start: `${dateValue.value}-01`, end: `${dateValue.value}-${lastDay}`, label: label || dateValue.value }; }
  if (precision.value === 'season') { if (!endValue.value) throw new Error('Enter the end of the stated release window.'); return { precision: 'season', start: dateValue.value, end: endValue.value, label }; }
  return { precision: 'day', start: dateValue.value, end: dateValue.value, label };
}
async function decide(action: 'approve' | 'reject') {
  if (!selected.value || !edited.value) return;
  saving.value = true;
  try { const payload = action === 'approve' ? { ...edited.value, release: releaseTime() } : undefined; await api(`/review/${selected.value.id}`, json({ action, payload })); selected.value = null; await load(); success(action === 'approve' ? 'Claim added to your personal timeline' : 'Claim rejected'); }
  catch (err) { report(err); }
  finally { saving.value = false; }
}
onMounted(() => void load());
</script>
<template>
  <q-page class="page"><PageHeading title="A little certainty goes a long way" subtitle="Inspect proposed claims before they enter your timeline."><q-btn outline no-caps icon="sync" label="Refresh queue" @click="load" /><q-btn unelevated color="primary" no-caps icon="add_link" label="Add source" to="/sources" /></PageHeading>
    <div class="review-intro"><q-icon name="fact_check" /><div><strong>You have the final say.</strong><p>Feed and model suggestions keep their source evidence. Approval adds a private event; its verification state is yours to choose.</p></div><span v-if="status === 'pending'" class="count-pill">{{ pending }} pending</span></div>
    <q-tabs v-model="status" no-caps align="left" active-color="primary" indicator-color="primary" class="detail-tabs" @update:model-value="load"><q-tab name="pending" label="Pending" /><q-tab name="approved" label="Approved" /><q-tab name="rejected" label="Rejected" /></q-tabs>
    <q-linear-progress v-if="loading" indeterminate />
    <div v-else-if="!proposals.length" class="empty-state"><span class="empty-symbol"><q-icon name="task_alt" /></span><h2>{{ status === 'pending' ? 'Nothing waiting for a second look' : 'No ' + status + ' claims yet' }}</h2><p>Add a source URL or monitor an official feed to collect proposals.</p><q-btn outline color="primary" no-caps label="Manage sources" to="/sources" /></div>
    <div v-else class="review-list"><button v-for="item in proposals" :key="item.id" class="review-card" @click="inspect(item)"><span class="review-symbol"><q-icon :name="item.model ? 'psychology' : 'rss_feed'" /></span><span class="review-card-content"><span class="eyebrow">{{ item.work_title }} · {{ eventLabel(item.payload.kind) }}</span><strong>{{ item.payload.title }}</strong><span>{{ item.payload.summary || item.payload.original_text }}</span><small>{{ item.model ? 'Extracted with ' + item.model : 'Source monitor' }} · {{ timestampLabel(item.created_at) }}</small></span><span :class="['trust-badge', item.payload.verification || 'unverified']">{{ item.payload.verification || 'unverified' }}</span><q-icon name="arrow_outward" /></button></div>
    <q-dialog :model-value="!!selected" position="right" maximized @update:model-value="value => { if (!value) selected = null; }"><q-card class="review-editor" v-if="selected && edited"><div class="drawer-header"><div><span class="eyebrow">REVIEW SOURCE CLAIM</span><h2>{{ selected.work_title }}</h2></div><q-btn flat round icon="close" aria-label="Close review" @click="selected = null" /></div><div class="review-editor-body"><section><h3>Source evidence</h3><a :href="selected.source_url" target="_blank" rel="noopener noreferrer" class="source-url">{{ selected.source_url }} <q-icon name="open_in_new" /></a><blockquote>{{ selected.payload.original_text || selected.excerpt }}</blockquote><q-expansion-item dense label="Read collected article text"><pre class="article-excerpt">{{ selected.excerpt }}</pre></q-expansion-item><p class="muted">{{ selected.model ? 'Model: ' + selected.model : 'Feed suggestion' }} · {{ timestampLabel(selected.created_at) }}</p></section><section class="form-stack"><h3>Proposed timeline event</h3><q-input v-model="edited.title" outlined label="Event title" :readonly="selected.status !== 'pending'" /><q-input v-model="edited.summary" outlined type="textarea" autogrow label="Summary" :readonly="selected.status !== 'pending'" /><div class="two-fields"><q-select v-model="edited.kind" :options="kinds.map(value => ({ label: eventLabel(value), value }))" emit-value map-options outlined label="Event type" :readonly="selected.status !== 'pending'" /><q-select v-model="edited.verification" :options="['confirmed', 'reported', 'unverified', 'contradicted', 'retracted']" outlined label="Verification" :readonly="selected.status !== 'pending'" /></div><div class="two-fields"><q-select v-model="precision" :options="['unknown', 'year', 'season', 'month', 'day', 'instant']" outlined label="Date precision" :readonly="selected.status !== 'pending'" /><q-select v-model="edited.lifecycle" :options="['announced', 'scheduled', 'released', 'delayed', 'cancelled']" outlined label="Lifecycle" :readonly="selected.status !== 'pending'" /></div><q-input v-if="precision !== 'unknown'" v-model="dateValue" :type="precision === 'day' || precision === 'season' ? 'date' : 'text'" outlined :label="precision === 'instant' ? 'ISO timestamp with timezone' : precision === 'year' ? 'Release year' : precision === 'month' ? 'Release month (YYYY-MM)' : precision === 'season' ? 'Window starts' : 'Release date'" :placeholder="precision === 'instant' ? '2027-04-02T21:00:00+09:00' : ''" :readonly="selected.status !== 'pending'" /><q-input v-if="precision === 'season'" v-model="endValue" type="date" outlined label="Window ends" :readonly="selected.status !== 'pending'" /><q-input v-model="dateLabel" outlined label="Original date wording" :readonly="selected.status !== 'pending'" /><div class="two-fields"><q-input v-model="edited.region" outlined label="Country code" :readonly="selected.status !== 'pending'" /><q-input v-model="edited.platform" outlined label="Platform / edition" :readonly="selected.status !== 'pending'" /></div><q-input v-model="edited.original_text" outlined type="textarea" label="Exact supporting quotation" :readonly="selected.status !== 'pending'" /><p class="muted">Year and month dates stay windows. Choose “unknown” when the source does not establish a date.</p></section></div><div v-if="selected.status === 'pending'" class="review-editor-footer"><q-btn outline no-caps color="negative" label="Reject claim" :disable="saving" @click="decide('reject')" /><q-space /><q-btn unelevated no-caps color="primary" icon="check" label="Approve to my timeline" :loading="saving" @click="decide('approve')" /></div></q-card></q-dialog>
  </q-page>
</template>
